mapper.select:
select p.point_id, p.tree_id, p.category_node_id, n.node_name as category_node_name, p.route_id, r.route_name, r.gcj02_path as route_gcj02_path, p.point_name, p.gcj02_lng, p.gcj02_lat, p.bd09_lng, p.bd09_lat, p.wgs84_lng, p.wgs84_lat, p.contact_name, p.contact_phone, p.status, p.create_time, p.remark from biz_scene_point p left join biz_tree_node n on n.node_id = p.category_node_id and n.del_flag = '0' left join biz_scene_route r on r.route_id = p.route_id and r.del_flag = '0'
p.del_flag = '0'
and p.point_name like concat('%', #{bo.pointName}, '%')
and p.route_id = #{bo.routeId}
and p.tree_id = #{bo.treeId}
and p.category_node_id = #{bo.categoryNodeId}
and p.status = #{bo.status}
order by p.create_time desc, p.point_id desc

